cssCode:
.gooey-wrap { filter: url(#gooey-filter); position: relative; width: 100px; height: 100px; }
.goo-btn, .goo-item {
  position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
  width: 60px; height: 60px; background: #00ffcc; border-radius: 50%;
  display: flex; align-items: center; justify-content: center; cursor: pointer;
  transition: transform 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
.goo-btn { z-index: 10; background: #ff007f; color: #fff; font-size: 30px; }
.gooey-wrap.active .item-1 { transform: translate(-50%, -150%); }
.gooey-wrap.active .item-2 { transform: translate(50%, -50%); }
.gooey-wrap.active .item-3 { transform: translate(-150%, -50%); }

